import{e,W as i,j as r,m as o}from"./chunks/framework.4B01ihDa.js";const m=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md","lastUpdated":1681202620000}'),a={name:"guide/introduction.md"};function l(n,t,s,d,u,c){return i(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>JustForFun-UI is a lightweight, high-performance Vue 3 component library designed for modern web applications.</p><h2 id="background" tabindex="-1">Background <a class="header-anchor" href="#background" aria-label="Permalink to &quot;Background&quot;">​</a></h2><p>In modern web development, UI component libraries play an important role in improving development efficiency. However, many existing component libraries have the following pain points:</p><ul><li><strong>Large bundle size</strong>: Traditional component libraries often include many unnecessary features, resulting in large package sizes</li><li><strong>Complex API</strong>: Overly complex APIs increase learning costs</li><li><strong>Lack of flexibility</strong>: Difficult to customize styles and behaviors</li><li><strong>Performance issues</strong>: Some libraries have performance bottlenecks in complex scenarios</li></ul><h2 id="goals" tabindex="-1">Goals <a class="header-anchor" href="#goals" aria-label="Permalink to &quot;Goals&quot;">​</a></h2><p>JustForFun-UI aims to solve these problems by:</p><ul><li>Providing a lightweight, high-performance Vue 3 component library</li><li>Simple and intuitive API design</li><li>Highly customizable flexibility</li><li>Excellent performance and developer experience</li></ul><h2 id="tech-stack" tabindex="-1">Tech Stack <a class="header-anchor" href="#tech-stack" aria-label="Permalink to &quot;Tech Stack&quot;">​</a></h2><ul><li><strong>Vue 3</strong> with Composition API</li><li><strong>TypeScript</strong> for type safety</li><li><strong>Vite</strong> for fast development and building</li><li><strong>SCSS</strong> with CSS variables for style management</li><li><strong>Vitest</strong> for unit testing</li></ul><h2 id="core-features" tabindex="-1">Core Features <a class="header-anchor" href="#core-features" aria-label="Permalink to &quot;Core Features&quot;">​</a></h2><ol><li><p><strong>Lightweight Architecture</strong></p><ul><li>Tree-shaking support for on-demand imports</li><li>Minimal dependencies</li><li>Small package size (less than 20KB after gzip)</li></ul></li><li><p><strong>Type Safety</strong></p><ul><li>Complete TypeScript support</li><li>Comprehensive type definitions</li><li>Smart IDE autocompletion</li></ul></li><li><p><strong>Customizable Themes</strong></p><ul><li>CSS variable-based theme system</li><li>Built-in dark mode support</li><li>Easy brand customization</li></ul></li><li><p><strong>Accessibility</strong></p><ul><li>WCAG 2.1 compliant</li><li>Keyboard navigation support</li><li>Screen reader compatible</li></ul></li><li><p><strong>Performance Optimized</strong></p><ul><li>Virtual scrolling for large data lists</li><li>Lazy loading support</li><li>Efficient re-rendering strategies</li></ul></li></ol><h2 id="results" tabindex="-1">Results <a class="header-anchor" href="#results" aria-label="Permalink to &quot;Results&quot;">​</a></h2><p>JustForFun-UI has achieved the following:</p><ul><li><strong>10+ production-ready components</strong>: Button, Input, Modal, DatePicker, etc.</li><li><strong>85% test coverage</strong>: Comprehensive unit testing ensures reliability</li><li><strong>35% development efficiency improvement</strong>: Used in 3+ internal projects</li><li><strong>Active community</strong>: Regular updates and maintenance</li></ul><h2 id="comparison" tabindex="-1">Comparison <a class="header-anchor" href="#comparison" aria-label="Permalink to &quot;Comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>JustForFun-UI</th><th>Element Plus</th><th>Ant Design Vue</th></tr></thead><tbody><tr><td>Bundle Size</td><td>~20KB</td><td>~150KB</td><td>~200KB</td></tr><tr><td>Vue 3 Support</td><td>Native</td><td>Native</td><td>Native</td></tr><tr><td>TypeScript</td><td>Full</td><td>Full</td><td>Full</td></tr><tr><td>On-demand Import</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>Dark Mode</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>Customizability</td><td>High</td><td>Medium</td><td>Medium</td></tr></tbody></table><h2 id="browser-compatibility" tabindex="-1">Browser Compatibility <a class="header-anchor" href="#browser-compatibility" aria-label="Permalink to &quot;Browser Compatibility&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Browser</th><th>Version</th></tr></thead><tbody><tr><td>Chrome</td><td>&gt;= 90</td></tr><tr><td>Firefox</td><td>&gt;= 88</td></tr><tr><td>Safari</td><td>&gt;= 14</td></tr><tr><td>Edge</td><td>&gt;= 90</td></tr><tr><td>IE</td><td>❌ Not Supported</td></tr></tbody></table><blockquote><p>Note: Internet Explorer is not supported due to Vue 3&#39;s minimum browser requirements.</p></blockquote>',20)])])}const h=e(a,[["render",l]]);export{m as __pageData,h as default};
